      ]
    },
    {
      "parameters": {
        "jsCode": "// =============================================================
// SMC Gold ULTIMATE - Corrected n8n Code Node
// Language: JavaScript
//
// Required nodes:
//   Fetch 15min Candles
//   Fetch 1H Candles
//
// Optional node:
//   Fetch Current Gold Price
//   Expected response: { "price": "4052.63" }
//
// IMPORTANT:
// Set timezone=UTC on both Twelve Data time_series nodes.
// =============================================================

const NODE_15M = 'Fetch 15min Candles';
const NODE_1H = 'Fetch 1H Candles';
const NODE_LIVE_PRICE = 'Fetch Current Gold Price';

const M15_MS = 15 * 60 * 1000;
const H1_MS = 60 * 60 * 1000;

const MAX_M15_AGE_MS = 20 * 60 * 1000;
const MAX_H1_AGE_MS = 2 * 60 * 60 * 1000;

const RECENT_FVG_BARS = 20;
const MIN_FVG_SIZE = 1.2;
const FVG_APPROACH_DISTANCE = 4.0;

const SL_BUFFER = 3.5;
const MIN_RISK = 1.5;
const MAX_RISK = 25.0;


// =============================================================
// OUTPUT HELPER
// =============================================================

function noSetup(reason, extra = {}) {
  return [{
    json: {
      hasSetup: false,
      reason,
      message: null,
      ...extra,
    },
  }];
}


function toNumber(value) {
  const number = Number(value);
  return Number.isFinite(number) ? number : NaN;
}


function round2(value) {
  return Number(Number(value).toFixed(2));
}


// =============================================================
// TIME HANDLING
// Assumes Twelve Data timestamps are configured in UTC.
// =============================================================

function parseTimestamp(value) {
  if (
    value === null ||
    value === undefined ||
    value === ''
  ) {
    return NaN;
  }

  const text = String(value).trim();

  const hasTimezone =
    /(?:Z|[+-]\d{2}:?\d{2})$/i.test(text);

  const isoText = text.includes('T')
    ? text
    : text.replace(' ', 'T');

  return Date.parse(
    hasTimezone ? isoText : `${isoText}Z`
  );
}


// =============================================================
// READ NODE DATA
// =============================================================

function getTimeSeriesData(nodeName) {
  try {
    return $(nodeName).first().json;
  } catch (error) {
    return null;
  }
}


function isSuccessfulTimeSeries(data) {
  return Boolean(
    data &&
    Array.isArray(data.values) &&
    data.values.length > 0 &&
    (!data.status || data.status === 'ok')
  );
}


// =============================================================
// NORMALIZE AND SORT CANDLES
// Oldest -> newest
// =============================================================

function normalizeCandles(values, nowMs) {
  return values
    .map((candle) => {
      const timeMs = parseTimestamp(candle.datetime);

      const open = toNumber(candle.open);
      const high = toNumber(candle.high);
      const low = toNumber(candle.low);
      const close = toNumber(candle.close);

      if (
        !Number.isFinite(timeMs) ||
        !Number.isFinite(open) ||
        !Number.isFinite(high) ||
        !Number.isFinite(low) ||
        !Number.isFinite(close) ||
        high < low ||
        timeMs > nowMs + 60_000
      ) {
        return null;
      }

      return {
        time: String(candle.datetime),
        timeMs,
        open,
        high,
        low,
        close,
      };
    })
    .filter(Boolean)
    .sort((a, b) => a.timeMs - b.timeMs);
}


// =============================================================
// EMA CALCULATION
// =============================================================

function calculateEMA(values, period) {
  if (
    !Array.isArray(values) ||
    values.length < period
  ) {
    return [];
  }

  const ema = new Array(values.length).fill(null);

  let sum = 0;

  for (let i = 0; i < period; i++) {
    sum += values[i];
  }

  ema[period - 1] = sum / period;

  const multiplier = 2 / (period + 1);

  for (let i = period; i < values.length; i++) {
    ema[i] =
      (values[i] - ema[i - 1]) * multiplier +
      ema[i - 1];
  }

  return ema;
}


// =============================================================
// FVG DETECTION
// =============================================================

function detectFVGs(candles) {
  const fvgs = [];

  for (let i = 2; i < candles.length; i++) {
    const c1 = candles[i - 2];
    const c2 = candles[i - 1];
    const c3 = candles[i];

    // BULLISH FVG
    // Candle 3 low must be above candle 1 high.
    // Middle candle must be bullish.

    if (
      c3.low > c1.high &&
      c2.close > c2.open
    ) {
      const bottom = c1.high;
      const top = c3.low;

      fvgs.push({
        type: 'BULLISH',
        top,
        bottom,
        ce: (top + bottom) / 2,
        index: i,
        time: c3.time,
        timeMs: c3.timeMs,
        size: top - bottom,
      });
    }

    // BEARISH FVG
    // Candle 3 high must be below candle 1 low.
    // Middle candle must be bearish.

    if (
      c3.high < c1.low &&
      c2.close < c2.open
    ) {
      const top = c1.low;
      const bottom = c3.high;

      fvgs.push({
        type: 'BEARISH',
        top,
        bottom,
        ce: (top + bottom) / 2,
        index: i,
        time: c3.time,
        timeMs: c3.timeMs,
        size: top - bottom,
      });
    }
  }

  return fvgs;
}


// =============================================================
// CHECK WHETHER FVG CE HAS ALREADY BEEN TOUCHED
// =============================================================

function isFVGUntouchedToCE(fvg, allCandles) {
  for (const candle of allCandles) {
    // Only candles formed after the FVG are relevant.
    if (candle.timeMs <= fvg.timeMs) {
      continue;
    }

    // Bullish FVG is consumed if price touches CE.
    if (
      fvg.type === 'BULLISH' &&
      candle.low <= fvg.ce
    ) {
      return false;
    }

    // Bearish FVG is consumed if price touches CE.
    if (
      fvg.type === 'BEARISH' &&
      candle.high >= fvg.ce
    ) {
      return false;
    }
  }

  return true;
}


// =============================================================
// OPTIONAL LIVE PRICE
// If the node is unavailable, use the latest M15 candle close.
// =============================================================

function getOptionalLivePrice() {
  try {
    const data = $(NODE_LIVE_PRICE).first().json;

    const rawPrice =
      data &&
      (data.price ?? data.close ?? data.value);

    const price = toNumber(rawPrice);

    return (
      Number.isFinite(price) && price > 0
    )
      ? price
      : null;

  } catch (error) {
    return null;
  }
}


// =============================================================
// LOAD SOURCE DATA
// =============================================================

const data15 = getTimeSeriesData(NODE_15M);
const data1h = getTimeSeriesData(NODE_1H);


if (!isSuccessfulTimeSeries(data15)) {
  return noSetup(
    'No valid 15m data from Twelve Data',
    {
      apiMessage:
        data15 &&
        (data15.message || data15.code) ||
        null,
    }
  );
}


if (!isSuccessfulTimeSeries(data1h)) {
  return noSetup(
    'No valid 1H data from Twelve Data',
    {
      apiMessage:
        data1h &&
        (data1h.message || data1h.code) ||
        null,
    }
  );
}


// =============================================================
// CLEAN AND VALIDATE CANDLES
// =============================================================

const nowMs = Date.now();

const allCandles15 = normalizeCandles(
  data15.values,
  nowMs
);

const allCandles1h = normalizeCandles(
  data1h.values,
  nowMs
);


// Use only fully closed candles for FVG detection
// and higher-timeframe analysis.

const candles15 = allCandles15.filter(
  candle => candle.timeMs + M15_MS <= nowMs
);

const candles1h = allCandles1h.filter(
  candle => candle.timeMs + H1_MS <= nowMs
);


if (candles15.length < 20) {
  return noSetup(
    'Not enough fully closed 15m candles',
    {
      closed15mCandles: candles15.length,
    }
  );
}


if (candles1h.length < 21) {
  return noSetup(
    'Not enough fully closed 1H candles to calculate EMA20',
    {
      closed1hCandles: candles1h.length,
    }
  );
}


const latestClosed15 =
  candles15[candles15.length - 1];

const latestClosed1h =
  candles1h[candles1h.length - 1];


const m15AgeMs =
  nowMs - (latestClosed15.timeMs + M15_MS);

const h1AgeMs =
  nowMs - (latestClosed1h.timeMs + H1_MS);


// Reject stale 15-minute data.

if (m15AgeMs > MAX_M15_AGE_MS) {
  return noSetup(
    '15m data is stale; signal blocked',
    {
      lastClosed15m: latestClosed15.time,
      m15AgeMinutes: Math.round(m15AgeMs / 60000),
    }
  );
}


// Reject stale higher-timeframe data.

if (h1AgeMs > MAX_H1_AGE_MS) {
  return noSetup(
    '1H data is stale; signal blocked',
    {
      lastClosed1h: latestClosed1h.time,
      h1AgeMinutes: Math.round(h1AgeMs / 60000),
    }
  );
}


// =============================================================
// REFERENCE PRICE
// =============================================================

const optionalLivePrice = getOptionalLivePrice();

const latestObserved15 =
  allCandles15[allCandles15.length - 1];


const price =
  optionalLivePrice !== null
    ? optionalLivePrice
    : (
        latestObserved15
          ? latestObserved15.close
          : latestClosed15.close
      );


const priceSource =
  optionalLivePrice !== null
    ? 'Fetch Current Gold Price'
    : 'Twelve Data latest 15m candle close';


if (
  !Number.isFinite(price) ||
  price <= 0
) {
  return noSetup(
    'No usable current/reference price',
    {
      price: null,
    }
  );
}


// =============================================================
// 1H BIAS USING EMA20 AND ITS DIRECTION
// =============================================================

const closes1h = candles1h.map(
  candle => candle.close
);

const ema20 = calculateEMA(closes1h, 20);

const lastEma = ema20[ema20.length - 1];
const previousEma = ema20[ema20.length - 2];

const last1h =
  candles1h[candles1h.length - 1];


let htfBias = 'NEUTRAL';


if (
  last1h.close > lastEma &&
  lastEma > previousEma
) {
  htfBias = 'BULLISH';

} else if (
  last1h.close < lastEma &&
  lastEma < previousEma
) {
  htfBias = 'BEARISH';
}


// =============================================================
// FIND RECENT FVGs
// =============================================================

const allFvgs = detectFVGs(candles15);


const recentFvgs = allFvgs
  .filter((fvg) => (
    fvg.index >= Math.max(
      2,
      candles15.length - RECENT_FVG_BARS
    ) &&
    fvg.size >= MIN_FVG_SIZE
  ))
  .sort((a, b) => b.index - a.index);


// =============================================================
// FIND A VALID TRADE SETUP
// =============================================================

let setup = null;

let rejectedOppositeBias = false;
let rejectedMitigated = false;
let rejectedPricePosition = false;


for (const fvg of recentFvgs) {

  // 1. Reject FVGs where CE was already touched.

  if (!isFVGUntouchedToCE(fvg, allCandles15)) {
    rejectedMitigated = true;
    continue;
  }


  // 2. Reject trades against the 1H direction.

  if (
    fvg.type === 'BULLISH' &&
    htfBias === 'BEARISH'
  ) {
    rejectedOppositeBias = true;
    continue;
  }


  if (
    fvg.type === 'BEARISH' &&
    htfBias === 'BULLISH'
  ) {
    rejectedOppositeBias = true;
    continue;
  }


  const entry = round2(fvg.ce);

  let sl;
  let tp1;
  let tp2;
  let risk;

  let direction;
  let type;

  let priceIsInValidApproachZone;


  // -----------------------------------------------------------
  // BULLISH SETUP
  // Price must still be above CE.
  // -----------------------------------------------------------

  if (fvg.type === 'BULLISH') {

    direction = 'BUY';

    type = 'Bullish FVG CE Retracement';

    sl = round2(
      fvg.bottom - SL_BUFFER
    );

    risk = round2(
      entry - sl
    );


    // Critical correction:
    // Do not issue BUY after price has crossed CE.

    priceIsInValidApproachZone = (
      price > entry &&
      price <= fvg.top + FVG_APPROACH_DISTANCE
    );


    tp1 = round2(
      entry + risk * 2
    );

    tp2 = round2(
      entry + risk * 3
    );

  } else {

    // ---------------------------------------------------------
    // BEARISH SETUP
    // Price must still be below CE.
    // ---------------------------------------------------------

    direction = 'SELL';

    type = 'Bearish FVG CE Retracement';

    sl = round2(
      fvg.top + SL_BUFFER
    );

    risk = round2(
      sl - entry
    );


    // Critical correction:
    // Do not issue SELL after price has crossed CE.

    priceIsInValidApproachZone = (
      price < entry &&
      price >= fvg.bottom - FVG_APPROACH_DISTANCE
    );


    tp1 = round2(
      entry - risk * 2
    );

    tp2 = round2(
      entry - risk * 3
    );
  }


  // 3. Reject a price that already passed the entry area.

  if (!priceIsInValidApproachZone) {
    rejectedPricePosition = true;
    continue;
  }


  // 4. Reject invalid stop distances.

  if (
    !Number.isFinite(risk) ||
    risk <= MIN_RISK ||
    risk >= MAX_RISK
  ) {
    continue;
  }


  let reason;


  if (htfBias === 'NEUTRAL') {

    reason =
      'FVG صالحة وغير مستهلكة، والسعر لم يتجاوز CE؛ ' +
      'اتجاه 1H محايد وليس تأكيدًا إضافيًا.';

  } else {

    reason =
      `FVG صالحة وغير مستهلكة، والسعر لم يتجاوز CE، ` +
      `واتجاه 1H ${htfBias}.`;
  }


  setup = {
    direction,
    type,

    entry,
    sl,
    tp1,
    tp2,

    rr: '1:2 → 1:3',

    fvgTop: round2(fvg.top),
    fvgBottom: round2(fvg.bottom),
    ce: round2(fvg.ce),

    fvgTime: fvg.time,

    htfBias,
    reason,

    confluence: [
      'FVG',
      'CE Retracement',
      `1H ${htfBias}`,
    ],
  };


  // Select the newest valid setup.

  break;
}


// =============================================================
// NO VALID SETUP
// =============================================================

if (!setup) {

  let reason =
    'No valid FVG CE setup at the reference price';

  if (rejectedMitigated) {
    reason += '; one or more FVGs already touched CE';
  }

  if (rejectedOppositeBias) {
    reason += '; opposite 1H bias';
  }

  if (rejectedPricePosition) {
    reason += '; price already passed the valid CE approach zone';
  }


  return noSetup(reason, {
    price,
    priceSource,
    htfBias,

    recentFVGs: recentFvgs.length,

    lastClosed15m: latestClosed15.time,
    lastClosed1h: latestClosed1h.time,
  });
}


// =============================================================
// TELEGRAM MESSAGE
// =============================================================

const dirEmoji =
  setup.direction === 'BUY' ? '🟢' : '🔴';

const dirText =
  setup.direction === 'BUY'
    ? 'شراء (BUY)'
    : 'بيع (SELL)';


const signalKey = [
  'XAUUSD',
  setup.direction,
  setup.fvgTime,
  setup.entry.toFixed(2),
  setup.sl.toFixed(2),
].join('|');


let msg = `<b>🟡 SMC Gold ULTIMATE</b>\n`;

msg += `━━━━━━━━━━━━━━━━━━━━\n`;

msg += `<b>الزوج:</b> XAUUSD (الذهب)\n`;

msg += `<b>الاتجاه:</b> ${dirEmoji} ${dirText}\n`;

msg += `<b>نوع الإعداد:</b> ${setup.type}\n\n`;

msg += `📍 <b>الدخول (CE Entry):</b> `;
msg += `<code>${setup.entry.toFixed(2)}</code>\n`;

msg += `🛑 <b>وقف الخسارة (SL):</b> `;
msg += `<code>${setup.sl.toFixed(2)}</code>\n`;

msg += `🎯 <b>الهدف 1 (TP1):</b> `;
msg += `<code>${setup.tp1.toFixed(2)}</code>\n`;

msg += `🎯 <b>الهدف 2 (TP2):</b> `;
msg += `<code>${setup.tp2.toFixed(2)}</code>\n`;

msg += `📊 <b>المخاطرة/العائد:</b> ${setup.rr}\n`;

msg += `💹 <b>السعر المرجعي:</b> `;
msg += `<code>${price.toFixed(2)}</code>\n\n`;

msg += `<b>تفاصيل FVG:</b>\n`;

msg += `• الأعلى: `;
msg += `<code>${setup.fvgTop.toFixed(2)}</code>\n`;

msg += `• الأدنى: `;
msg += `<code>${setup.fvgBottom.toFixed(2)}</code>\n`;

msg += `• المنتصف (CE): `;
msg += `<code>${setup.ce.toFixed(2)}</code>\n\n`;

msg += `🧠 <b>التوافق:</b> `;
msg += `${setup.confluence.join(' + ')}\n`;

msg += `📈 <b>اتجاه 1H:</b> ${setup.htfBias}\n`;

msg += `💬 ${setup.reason}\n\n`;

msg += `━━━━━━━━━━━━━━━━━━━━\n`;

msg += `⚠️ <b>تنبيه يدوي؛ تحقق من السعر والتنفيذ قبل الدخول.</b>\n`;

msg += `🕐 ${new Date().toLocaleString('ar-DZ', {
  timeZone: 'Africa/Algiers',
})}`;


// =============================================================
// FINAL OUTPUT
// Compatible with Has Valid Setup? and Telegram nodes.
// =============================================================

return [{
  json: {
    hasSetup: true,

    direction: setup.direction,
    type: setup.type,

    entry: setup.entry,
    sl: setup.sl,
    tp1: setup.tp1,
    tp2: setup.tp2,

    rr: setup.rr,

    price,
    priceSource,

    htfBias: setup.htfBias,

    fvgTop: setup.fvgTop,
    fvgBottom: setup.fvgBottom,
    ce: setup.ce,
    fvgTime: setup.fvgTime,

    signalKey,

    message: msg,
  },
}];"
      },
